import { FileTree } from '@principal-ai/repository-abstraction';
import { BaseLayer, FileSet } from '../types/layer-types';

export interface FileTypeInfo {
  extension: string;
  name: string;
  count: number;
  files: string[];
  color: string;
  icon: string;
  category?: string;
}

