  // Config files
  '.json': { name: 'JSON', color: '#90a4ae', icon: 'file-json', category: 'config' },
  '.yaml': { name: 'YAML', color: '#cb171e', icon: 'file-text', category: 'config' },
  '.yml': { name: 'YAML', color: '#cb171e', icon: 'file-text', category: 'config' },
